def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows=[r for r,row in enumerate(grid) if len(set(row))==1 and row[0]!=bg]
    sep_cols=[c for c in range(w) if len({grid[r][c] for r in range(h)})==1 and grid[0][c]!=bg]
    # Data panels are the intervals between full divider lines.
    def intervals(n, cuts):
        out=[]; start=0
        for x in cuts:
            if start<x: out.append((start,x))
            start=x+1
        if start<n: out.append((start,n))
        return out
    rs=intervals(h,sep_rows); cs=intervals(w,sep_cols)
    # Select the panel containing the most non-background cells.
    panels=[]
    for ri,(r0,r1) in enumerate(rs):
        for ci,(c0,c1) in enumerate(cs):
            score=sum(grid[r][c]!=bg for r in range(r0,r1) for c in range(c0,c1))
            panels.append((score,ri,ci,r0,r1,c0,c1))
    _,sri,sci,sr0,sr1,sc0,sc1=max(panels)
    tile=[row[sc0:sc1] for row in grid[sr0:sr1]]
    out=[row[:] for row in grid]
    for ri,(r0,r1) in enumerate(rs):
        for ci,(c0,c1) in enumerate(cs):
            for r in range(r0,r1):
                for c in range(c0,c1):
                    out[r][c]=tile[(r-r0)%(sr1-sr0)][(c-c0)%(sc1-sc0)]
    return out
